// Type: What.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum What {
    Repository,
    Branch(Segments),
    Pull(Number),
    Issue(Number),
}

// Record: What.
impl Record for What {
    type Limits = Limits;
    const TAIL: Path = paths::WHAT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 14)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 14)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Repository => field::put(out, &[0], paths::WHAT_TAG),
            Self::Branch(value) => { field::put(out, &[1], paths::WHAT_TAG)?; value.write(limits, out) },
            Self::Pull(value) => { field::put(out, &[2], paths::WHAT_TAG)?; value.write(limits, out) },
            Self::Issue(value) => { field::put(out, &[3], paths::WHAT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::WHAT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Repository),
            1 => Ok(Self::Branch(Segments::read(limits, reader)?)),
            2 => Ok(Self::Pull(Number::read(limits, reader)?)),
            3 => Ok(Self::Issue(Number::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::WHAT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

