// Type: MergeHow.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum MergeHow {
    Style,
    FastForwardOnly,
    Recorded(RecordedMerge),
}

// Record: MergeHow.
impl Record for MergeHow {
    type Limits = Limits;
    const TAIL: Path = paths::MERGE_HOW_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 209)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 209)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Style => field::put(out, &[0], paths::MERGE_HOW_TAG),
            Self::FastForwardOnly => field::put(out, &[1], paths::MERGE_HOW_TAG),
            Self::Recorded(value) => { field::put(out, &[2], paths::MERGE_HOW_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::MERGE_HOW_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Style),
            1 => Ok(Self::FastForwardOnly),
            2 => Ok(Self::Recorded(RecordedMerge::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::MERGE_HOW_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

