// Type: Write.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Write {
    CreateIssue(CreateIssue),
    OpenPull(OpenPull),
    Post(Post),
    Review(PostReview),
    Edit(Edit),
    SetReviewers(SetReviewers),
    Close(Number),
    Reopen(Number),
    Merge(MergeWrite),
    Update(UpdateWrite),
    Status(SetStatus),
    CreateBranch(CreateBranch),
    DeleteBranch(DeleteBranch),
    Dispatch(DispatchWrite),
    Rerun(JobAttempt),
}

// Record: Write.
impl Record for Write {
    type Limits = Limits;
    const TAIL: Path = paths::WRITE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 235)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 235)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::CreateIssue(value) => { field::put(out, &[0], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::OpenPull(value) => { field::put(out, &[1], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Post(value) => { field::put(out, &[2], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Review(value) => { field::put(out, &[3], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Edit(value) => { field::put(out, &[4], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::SetReviewers(value) => { field::put(out, &[5], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Close(value) => { field::put(out, &[6], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Reopen(value) => { field::put(out, &[7], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Merge(value) => { field::put(out, &[8], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Update(value) => { field::put(out, &[9], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Status(value) => { field::put(out, &[10], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::CreateBranch(value) => { field::put(out, &[11], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::DeleteBranch(value) => { field::put(out, &[12], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Dispatch(value) => { field::put(out, &[13], paths::WRITE_TAG)?; value.write(limits, out) },
            Self::Rerun(value) => { field::put(out, &[14], paths::WRITE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::WRITE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::CreateIssue(CreateIssue::read(limits, reader)?)),
            1 => Ok(Self::OpenPull(OpenPull::read(limits, reader)?)),
            2 => Ok(Self::Post(Post::read(limits, reader)?)),
            3 => Ok(Self::Review(PostReview::read(limits, reader)?)),
            4 => Ok(Self::Edit(Edit::read(limits, reader)?)),
            5 => Ok(Self::SetReviewers(SetReviewers::read(limits, reader)?)),
            6 => Ok(Self::Close(Number::read(limits, reader)?)),
            7 => Ok(Self::Reopen(Number::read(limits, reader)?)),
            8 => Ok(Self::Merge(MergeWrite::read(limits, reader)?)),
            9 => Ok(Self::Update(UpdateWrite::read(limits, reader)?)),
            10 => Ok(Self::Status(SetStatus::read(limits, reader)?)),
            11 => Ok(Self::CreateBranch(CreateBranch::read(limits, reader)?)),
            12 => Ok(Self::DeleteBranch(DeleteBranch::read(limits, reader)?)),
            13 => Ok(Self::Dispatch(DispatchWrite::read(limits, reader)?)),
            14 => Ok(Self::Rerun(JobAttempt::read(limits, reader)?)),
            15..=u8::MAX => Err(Problem { path: paths::WRITE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

