// Type: Delegate.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Delegate {
    Produce,
    Repair(RepairValue),
    Resolve(Commit),
    Gate(DelegateGate),
    Merge(MergeDelegate),
    Close,
}

// Record: Delegate.
impl Record for Delegate {
    type Limits = Limits;
    const TAIL: Path = paths::DELEGATE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 606)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 606)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Produce => field::put(out, &[0], paths::DELEGATE_TAG),
            Self::Repair(value) => { field::put(out, &[1], paths::DELEGATE_TAG)?; value.write(limits, out) },
            Self::Resolve(value) => { field::put(out, &[2], paths::DELEGATE_TAG)?; value.write(limits, out) },
            Self::Gate(value) => { field::put(out, &[3], paths::DELEGATE_TAG)?; value.write(limits, out) },
            Self::Merge(value) => { field::put(out, &[4], paths::DELEGATE_TAG)?; value.write(limits, out) },
            Self::Close => field::put(out, &[5], paths::DELEGATE_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::DELEGATE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Produce),
            1 => Ok(Self::Repair(RepairValue::read(limits, reader)?)),
            2 => Ok(Self::Resolve(Commit::read(limits, reader)?)),
            3 => Ok(Self::Gate(DelegateGate::read(limits, reader)?)),
            4 => Ok(Self::Merge(MergeDelegate::read(limits, reader)?)),
            5 => Ok(Self::Close),
            6..=u8::MAX => Err(Problem { path: paths::DELEGATE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

