// Type: ChangeLive.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ChangeLive {
    Producing(Producing),
    Opening(Producing),
    Recreating(ChangeHead),
    Reopening(Reopening),
    Checking(ChangeHead),
    Gating(Gating),
    Queued(ReadyHead),
    First(ReadyHead),
    Updating(Updating),
    Resolving(Resolving),
    Repairing(Repairing),
    Landing(ChangeHead),
    Landed(LandedChange),
    Ended,
    CancellingGates(ChangeHead),
    Ready(ReadyHead),
    Preparing(Preparing),
    NoChange(NoChange),
    Red(LandedChange),
    Cleared(MergeChange),
    Uncleared(MergeChange),
    WaitingProducer(WaitingProducer),
    Judging(Judging),
    Taking(Producing),
}

// Record: ChangeLive.
impl Record for ChangeLive {
    type Limits = Limits;
    const TAIL: Path = paths::CHANGE_LIVE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 658)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 658)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Producing(value) => { field::put(out, &[0], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Opening(value) => { field::put(out, &[1], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Recreating(value) => { field::put(out, &[2], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Reopening(value) => { field::put(out, &[3], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Checking(value) => { field::put(out, &[4], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Gating(value) => { field::put(out, &[5], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Queued(value) => { field::put(out, &[6], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::First(value) => { field::put(out, &[7], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Updating(value) => { field::put(out, &[8], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Resolving(value) => { field::put(out, &[9], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Repairing(value) => { field::put(out, &[10], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Landing(value) => { field::put(out, &[11], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Landed(value) => { field::put(out, &[12], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Ended => field::put(out, &[13], paths::CHANGE_LIVE_TAG),
            Self::CancellingGates(value) => { field::put(out, &[14], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Ready(value) => { field::put(out, &[15], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Preparing(value) => { field::put(out, &[16], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::NoChange(value) => { field::put(out, &[17], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Red(value) => { field::put(out, &[18], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Cleared(value) => { field::put(out, &[19], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Uncleared(value) => { field::put(out, &[20], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::WaitingProducer(value) => { field::put(out, &[21], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Judging(value) => { field::put(out, &[22], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
            Self::Taking(value) => { field::put(out, &[23], paths::CHANGE_LIVE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::CHANGE_LIVE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Producing(Producing::read(limits, reader)?)),
            1 => Ok(Self::Opening(Producing::read(limits, reader)?)),
            2 => Ok(Self::Recreating(ChangeHead::read(limits, reader)?)),
            3 => Ok(Self::Reopening(Reopening::read(limits, reader)?)),
            4 => Ok(Self::Checking(ChangeHead::read(limits, reader)?)),
            5 => Ok(Self::Gating(Gating::read(limits, reader)?)),
            6 => Ok(Self::Queued(ReadyHead::read(limits, reader)?)),
            7 => Ok(Self::First(ReadyHead::read(limits, reader)?)),
            8 => Ok(Self::Updating(Updating::read(limits, reader)?)),
            9 => Ok(Self::Resolving(Resolving::read(limits, reader)?)),
            10 => Ok(Self::Repairing(Repairing::read(limits, reader)?)),
            11 => Ok(Self::Landing(ChangeHead::read(limits, reader)?)),
            12 => Ok(Self::Landed(LandedChange::read(limits, reader)?)),
            13 => Ok(Self::Ended),
            14 => Ok(Self::CancellingGates(ChangeHead::read(limits, reader)?)),
            15 => Ok(Self::Ready(ReadyHead::read(limits, reader)?)),
            16 => Ok(Self::Preparing(Preparing::read(limits, reader)?)),
            17 => Ok(Self::NoChange(NoChange::read(limits, reader)?)),
            18 => Ok(Self::Red(LandedChange::read(limits, reader)?)),
            19 => Ok(Self::Cleared(MergeChange::read(limits, reader)?)),
            20 => Ok(Self::Uncleared(MergeChange::read(limits, reader)?)),
            21 => Ok(Self::WaitingProducer(WaitingProducer::read(limits, reader)?)),
            22 => Ok(Self::Judging(Judging::read(limits, reader)?)),
            23 => Ok(Self::Taking(Producing::read(limits, reader)?)),
            24..=u8::MAX => Err(Problem { path: paths::CHANGE_LIVE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

