// Type: ForgeReason.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ForgeReason {
    NoSuchForge,
    NotFound,
    NoAccess,
    Refused,
    InFlight,
    TooLarge,
    Unreachable,
    InvalidAnswer,
    NotInstalled,
    AnotherProject,
    HomeHeld,
    PrefixOccupied,
}

// Record: ForgeReason.
impl Record for ForgeReason {
    type Limits = Limits;
    const TAIL: Path = paths::FORGE_REASON_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 856)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 856)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::NoSuchForge => field::put(out, &[0], paths::FORGE_REASON_TAG),
            Self::NotFound => field::put(out, &[1], paths::FORGE_REASON_TAG),
            Self::NoAccess => field::put(out, &[2], paths::FORGE_REASON_TAG),
            Self::Refused => field::put(out, &[3], paths::FORGE_REASON_TAG),
            Self::InFlight => field::put(out, &[4], paths::FORGE_REASON_TAG),
            Self::TooLarge => field::put(out, &[5], paths::FORGE_REASON_TAG),
            Self::Unreachable => field::put(out, &[6], paths::FORGE_REASON_TAG),
            Self::InvalidAnswer => field::put(out, &[7], paths::FORGE_REASON_TAG),
            Self::NotInstalled => field::put(out, &[8], paths::FORGE_REASON_TAG),
            Self::AnotherProject => field::put(out, &[9], paths::FORGE_REASON_TAG),
            Self::HomeHeld => field::put(out, &[10], paths::FORGE_REASON_TAG),
            Self::PrefixOccupied => field::put(out, &[11], paths::FORGE_REASON_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::FORGE_REASON_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::NoSuchForge),
            1 => Ok(Self::NotFound),
            2 => Ok(Self::NoAccess),
            3 => Ok(Self::Refused),
            4 => Ok(Self::InFlight),
            5 => Ok(Self::TooLarge),
            6 => Ok(Self::Unreachable),
            7 => Ok(Self::InvalidAnswer),
            8 => Ok(Self::NotInstalled),
            9 => Ok(Self::AnotherProject),
            10 => Ok(Self::HomeHeld),
            11 => Ok(Self::PrefixOccupied),
            12..=u8::MAX => Err(Problem { path: paths::FORGE_REASON_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

