// Type: LandingLeave.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LandingLeave {
    Conflict,
    HeadMoved(Commit),
    Cancelled,
    Held,
    Refused(LandingGateRefused),
    Failed(LandingGateFailed),
    EarlierConflict,
    Unit(LandingLeftChange),
    Dependency(LandingLeftChange),
    Fallback(LandingFallback),
    Blamed(LandingBlamed),
}

// Record: LandingLeave.
impl Record for LandingLeave {
    type Limits = Limits;
    const TAIL: Path = paths::LANDING_LEAVE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 998)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 998)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Conflict => field::put(out, &[0], paths::LANDING_LEAVE_TAG),
            Self::HeadMoved(value) => { field::put(out, &[1], paths::LANDING_LEAVE_TAG)?; value.write(limits, out) },
            Self::Cancelled => field::put(out, &[2], paths::LANDING_LEAVE_TAG),
            Self::Held => field::put(out, &[3], paths::LANDING_LEAVE_TAG),
            Self::Refused(value) => { field::put(out, &[4], paths::LANDING_LEAVE_TAG)?; value.write(limits, out) },
            Self::Failed(value) => { field::put(out, &[5], paths::LANDING_LEAVE_TAG)?; value.write(limits, out) },
            Self::EarlierConflict => field::put(out, &[6], paths::LANDING_LEAVE_TAG),
            Self::Unit(value) => { field::put(out, &[7], paths::LANDING_LEAVE_TAG)?; value.write(limits, out) },
            Self::Dependency(value) => { field::put(out, &[8], paths::LANDING_LEAVE_TAG)?; value.write(limits, out) },
            Self::Fallback(value) => { field::put(out, &[9], paths::LANDING_LEAVE_TAG)?; value.write(limits, out) },
            Self::Blamed(value) => { field::put(out, &[10], paths::LANDING_LEAVE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::LANDING_LEAVE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Conflict),
            1 => Ok(Self::HeadMoved(Commit::read(limits, reader)?)),
            2 => Ok(Self::Cancelled),
            3 => Ok(Self::Held),
            4 => Ok(Self::Refused(LandingGateRefused::read(limits, reader)?)),
            5 => Ok(Self::Failed(LandingGateFailed::read(limits, reader)?)),
            6 => Ok(Self::EarlierConflict),
            7 => Ok(Self::Unit(LandingLeftChange::read(limits, reader)?)),
            8 => Ok(Self::Dependency(LandingLeftChange::read(limits, reader)?)),
            9 => Ok(Self::Fallback(LandingFallback::read(limits, reader)?)),
            10 => Ok(Self::Blamed(LandingBlamed::read(limits, reader)?)),
            11..=u8::MAX => Err(Problem { path: paths::LANDING_LEAVE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

